  const explicit = items.some((item) => END_LINE.test(item.text.trim()) || /^\}\s*(?:else|while)\b/i.test(item.text.trim()));

  const nodes = [];
  // Open blocks: the list new lines go into, the node owning it, its indent, and whether it
